1	// Shared drawing helpers for the Loupe direction. Everything is emitted as static SVG/HTML at build time.
2	
3	export const f = (n) => +(+n).toFixed(1);
4	
5	export function rng(seed) {
6	  let a = (seed * 2654435761) >>> 0;
7	  return () => {
8	    a |= 0; a = (a + 0x6d2b79f5) | 0;
9	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
10	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
11	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
12	  };
13	}
14	
15	function smooth(pts) {
16	  let d = `M${f(pts[0][0])},${f(pts[0][1])}`;
17	  for (let i = 0; i < pts.length - 1; i++) {
18	    const p0 = pts[Math.max(i - 1, 0)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(i + 2, pts.length - 1)];
19	    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
20	    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
21	    d += ` C${f(c1[0])},${f(c1[1])} ${f(c2[0])},${f(c2[1])} ${f(p2[0])},${f(p2[1])}`;
22	  }
23	  return d;
24	}
25	
26	/* ---------- grease pencil geometry ---------- */
27	
28	// A hand-drawn loop: starts at the left, goes over the top, and overshoots its own start.
29	export function ringD(cx, cy, rx, ry, o = {}) {
30	  const { seed = 1, turns = 1.15, start = Math.PI * 0.97, wob = 0.035, tilt = -0.05, drift = -0.1, steps = 30 } = o;
31	  const r = rng(seed * 7919 + 13);
32	  const h1 = r() * 6.28, h2 = r() * 6.28, a1 = wob * (0.7 + r() * 0.6), a2 = wob * 0.6 * (0.7 + r() * 0.6);
33	  const total = Math.PI * 2 * turns, pts = [];
34	  for (let i = 0; i <= steps; i++) {
35	    const t = i / steps, a = start + total * t;
36	    const k = 1 + a1 * Math.sin(a + h1) + a2 * Math.sin(a * 2.3 + h2) + drift * (t - 0.5);
37	    const x = Math.cos(a) * rx * k, y = Math.sin(a) * ry * k;
38	    pts.push([cx + x * Math.cos(tilt) - y * Math.sin(tilt), cy + x * Math.sin(tilt) + y * Math.cos(tilt)]);
39	  }
40	  return smooth(pts);
41	}
42	
43	export function crossD(cx, cy, w, h, o = {}) {
44	  const { seed = 1 } = o;
45	  const r = rng(seed * 104729 + 7), j = (m) => (r() - 0.5) * m;
46	  const x1 = cx - w / 2, x2 = cx + w / 2, y1 = cy - h / 2, y2 = cy + h / 2;
47	  const a = `M${f(x1 + j(w * 0.05))},${f(y1 + j(h * 0.08))} C${f(cx - w * 0.2)},${f(cy - h * 0.2 + j(h * 0.1))} ${f(cx + w * 0.16)},${f(cy + h * 0.12 + j(h * 0.1))} ${f(x2 + j(w * 0.05))},${f(y2 + j(h * 0.08))}`;
48	  const b = `M${f(x2 + j(w * 0.05))},${f(y1 + j(h * 0.08))} C${f(cx + w * 0.18)},${f(cy - h * 0.16 + j(h * 0.1))} ${f(cx - w * 0.2)},${f(cy + h * 0.2 + j(h * 0.1))} ${f(x1 + j(w * 0.05))},${f(y2 + j(h * 0.08))}`;
49	  return a + ' ' + b;
50	}
51	
52	// Question mark in a box `h` tall, centred on cx,cy.
53	export function qD(cx, cy, h) {
54	  const s = h / 100, P = (x, y) => `${f(cx + x * s)},${f(cy + y * s)}`;
55	  return `M${P(-23, -23)} C${P(-25, -57)} ${P(27, -59)} ${P(26, -27)} C${P(25, -6)} ${P(1, -5)} ${P(0, 19)} M${P(-1, 43)} L${P(1, 45)}`;
56	}
57	
58	export function underD(x1, x2, y, o = {}) {
59	  const { seed = 1, amp = 4 } = o;
60	  const r = rng(seed * 31 + 5), n = 5, pts = [];
61	  for (let i = 0; i <= n; i++) pts.push([x1 + ((x2 - x1) * i) / n, y + (r() - 0.5) * amp * 2 - (i / n - 0.5) * amp * 1.5]);
62	  return smooth(pts);
63	}
64	
65	// Wrap pencil paths. `filter` is one of pencil | pencilBig | pencilSm | none.
66	export function pencil(paths, o = {}) {
67	  const { sw = 8, filter = 'pencilBig', dash = '', pad = '', extra = '' } = o;
68	  const d = Array.isArray(paths) ? paths : [paths];
69	  return `<g fill="none" stroke="#ffd60a" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"${filter === 'none' ? '' : ` filter="url(#${filter})"`}${dash ? ` stroke-dasharray="${dash}"` : ''}${extra ? ' ' + extra : ''}>${pad ? `<path d="${pad}" stroke="none"/>` : ''}${d.map((p) => `<path d="${p}"/>`).join('')}</g>`;
70	}
71	
72	/* ---------- verdict marks for UI (small, inline) ---------- */
73	// kind: verified | contradicted | stale | unverified
74	export function mark(kind, size = 28, o = {}) {
75	  const { sw = 4.6, seed = 3, cls = '' } = o;
76	  let inner;
77	  if (kind === 'verified') inner = `<path d="${ringD(24, 24, 17, 15.5, { seed, wob: 0.05, turns: 1.13 })}"/>`;
78	  else if (kind === 'stale') inner = `<path d="${ringD(24, 24, 17, 15.5, { seed, wob: 0.05, turns: 1.0, drift: 0 })}" stroke-dasharray="8.5 8"/>`;
79	  else if (kind === 'contradicted') inner = `<path d="${crossD(24, 24, 31, 31, { seed })}"/>`;
80	  else inner = `<path d="${qD(24, 23, 40)}"/>`;
81	  return `<svg class="mk mk-${kind}${cls ? ' ' + cls : ''}" width="${size}" height="${size}" viewBox="0 0 48 48" aria-hidden="true"><g fill="none" stroke="#ffd60a" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round">${inner}</g></svg>`;
82	}
83	
84	// A phrase ringed in pencil, robust to reflow: the SVG stretches to the span's box.
85	export function ringSpan(text, o = {}) {
86	  const { seed = 5, sw = 3.2, cls = '', filter = 'pencilSm' } = o;
87	  return `<span class="pr${cls ? ' ' + cls : ''}">${text}<svg viewBox="0 0 300 100" preserveAspectRatio="none" aria-hidden="true"><path d="${ringD(150, 50, 138, 40, { seed, wob: 0.03, tilt: -0.015, turns: 1.07, drift: -0.05, start: Math.PI * 0.9 })}" fill="none" stroke="#ffd60a" stroke-width="${sw}" stroke-linecap="round" vector-effect="non-scaling-stroke"${filter === 'none' ? '' : ` filter="url(#${filter})"`}/></svg></span>`;
88	}
