92	// Horizontal strip. Default frames are 8-perf landscape (3:2); half:true gives 4-perf portrait half-frames.
93	export function hstrip(o) {
94	  const { id, P, x0, y0, k0 = -1, k1 = 4, rot = -2, rcx = 960, rcy = 540, half = false, fills = {}, base = '#070a09', perf = '#1c2724', frame = '#131c19' } = o;
95	  const U = half ? P * 2 : P;
96	  const H = 0.9215 * U, pw = 0.0523 * U, ph = 0.0735 * U, cell = U / 8, gap = 0.0523 * U;
97	  const fy = y0 + 0.1445 * U, fh = 0.6314 * U, fw = P - gap;
98	  const X0 = x0 + k0 * P - 400, X1 = x0 + (k1 + 1) * P + 400;
99	  const fx = (k) => x0 + k * P + gap / 2;
100	  let rects = '';
101	  for (let k = k0; k <= k1; k++) rects += `<rect x="${f(fx(k))}" y="${f(fy)}" width="${f(fw)}" height="${f(fh)}" rx="${f(Math.max(3, U * 0.0105))}" fill="${fills[k] || frame}"/>`;
102	  const open = `<g id="${id}" transform="rotate(${rot} ${rcx} ${rcy})">`;
103	  const body = `<rect x="${f(X0)}" y="${f(y0)}" width="${f(X1 - X0)}" height="${f(H)}" fill="${base}"/><rect x="${f(X0)}" y="${f(y0)}" width="${f(X1 - X0)}" height="${f(H)}" fill="url(#${id}P)"/><path d="M${f(X0)},${f(y0 + 1)}H${f(X1)}M${f(X0)},${f(y0 + H - 1)}H${f(X1)}" stroke="#eef3f1" stroke-opacity=".16" stroke-width="2"/>${rects}`;
104	  const defs = `<pattern id="${id}P" patternUnits="userSpaceOnUse" x="${f(x0)}" y="${f(y0)}" width="${f(cell)}" height="${f(H)}"><rect x="${f((cell - pw) / 2)}" y="${f(0.0523 * U)}" width="${f(pw)}" height="${f(ph)}" rx="${f(U * 0.01)}" fill="${perf}"/><rect x="${f((cell - pw) / 2)}" y="${f(H - 0.0523 * U - ph)}" width="${f(pw)}" height="${f(ph)}" rx="${f(U * 0.01)}" fill="${perf}"/></pattern>`;
105	  return { id, open, body, close: '</g>', defs, fx, fy, fw, fh, H, y0, P, U, cx: (k) => fx(k) + fw / 2, cy: fy + fh / 2, top: y0, bottom: y0 + H, rot, rcx, rcy,
106	    // y of the strip centre line at screen x, after rotation
107	    yAt: (x) => y0 + H / 2 + (x - rcx) * Math.tan((rot * Math.PI) / 180) - (y0 + H / 2 - rcy) * (1 - Math.cos((rot * Math.PI) / 180)) };
108	}
