110	// Greeked content for an unlit frame: a few soft bars.
111	export function greek(x, y, w, h, seed, o = {}) {
112	  const { bar = 9, op = 0.1, n } = o;
113	  const r = rng(seed * 97 + 3);
114	  const rows = n || 3 + Math.floor(r() * 3);
115	  let s = '';
116	  for (let i = 0; i < rows; i++) {
117	    const bw = w * (0.25 + r() * 0.55);
118	    s += `<rect x="${f(x)}" y="${f(y + i * bar * 2.4)}" width="${f(bw)}" height="${f(bar)}" rx="${f(bar / 2)}" fill="#eef3f1" opacity="${(op * (0.6 + r() * 0.8)).toFixed(2)}"/>`;
119	  }
120	  return s;
