import { FONTS, DEFS, BASE_CSS, COMMENT } from './defs.mjs';
import { f, mark, hstrip, loupe, refract, pencil, ringD } from './lib.mjs';
import { PILL_CSS, tx } from './parts.mjs';
import { APP_CSS, meter } from './reel.mjs';

const STAGES = [
  ['ingest', 'done', '0:07', ['4 sessions', '212 tool calls']],
  ['edit', 'done', '0:05', ['96 minutes', 'cut to 7 scenes']],
  ['verify', 'done', '0:07', ['8 claims', '2 flagged']],
  ['script', 'done', '0:08', ['5 lines', '1 sent back']],
  ['ground', 'running', '', []],
  ['voice', 'waiting', '', []],
  ['render', 'waiting', '', []],
  ['review', 'waiting', '', []],
  ['gate', 'waiting', '', []],
];

function stageStrip() {
  const W = 1440, P = 160, yc = 180;
  const S = hstrip({ id: 'rs', P, x0: 0, y0: yc - 147.4, k0: -2, k1: 10, half: true, rot: -1.2, rcx: W / 2, rcy: yc, frame: '#0f1614' });
  let c = '';
  STAGES.forEach(([name, state, dur, lines], k) => {
    const x = S.fx(k), cx = S.cx(k), y = S.fy;
    if (state === 'done') {
      c += `<rect x="${f(x)}" y="${f(y)}" width="${f(S.fw)}" height="${f(S.fh)}" rx="3.4" fill="#1b2824"/>`;
      c += tx('disp', cx, y + 36, 17, name, { w: 600, anchor: 'middle' });
      lines.forEach((l, i) => { c += tx('txt', cx, y + 150 + i * 21, 14.5, l, { fill: '#c3cfca', anchor: 'middle' }); });
      c += tx('mono', cx, S.bottom - 7, 11, `done ${dur}`, { op: 0.62, ls: 0.4, anchor: 'middle' });
    } else if (state === 'running') {
      c += tx('mono', cx, S.bottom - 7, 11, 'running', { op: 0.9, ls: 0.4, anchor: 'middle' });
    } else {
      c += tx('disp', cx, y + 36, 17, name, { w: 600, op: 0.42, anchor: 'middle' });
      c += tx('mono', cx, S.bottom - 7, 11, 'waiting', { op: 0.4, ls: 0.4, anchor: 'middle' });
    }
    c += tx('mono', cx, S.top + 13, 11, String(k + 1), { op: 0.36, anchor: 'middle' });
  });
  const lx = S.cx(4), ly = yc, s = 0.345;
  const lens = `<circle r="600" fill="#2a3f38"/>${tx('disp', 0, -33, 16.5, 'ground', { w: 600, anchor: 'middle' })}${tx('disp', 0, 15, 41, '4 of 5', { w: 800, anchor: 'middle', ls: -1 })}${tx('txt', 0, 40, 13, 'lines have a source', { w: 500, anchor: 'middle', fill: '#dfe6e3' })}`;
  return `<svg class="stages" viewBox="0 0 ${W} 360" role="img" aria-label="Nine stages. Ingest, edit, verify and script are done. Ground is running: 4 of 5 lines have a source. Voice, render, review and gate are waiting.">
    <defs>${S.defs}</defs>
    ${S.open}${S.body}${c}${S.close}
    <circle cx="${f(lx)}" cy="${ly}" r="300" fill="url(#spillG)"/>
    ${loupe({ x: lx, y: ly, s, lens, under: refract(S.id, lx, ly) })}
  </svg>`;
}

const LOG = [
  ['00:02', 'ingest', 'Read 4 sessions from the Entire checkpoints: 212 tool calls, 9 commits.', ''],
  ['00:09', 'edit', 'Cut 96 minutes down to 7 scenes.', ''],
  ['00:14', 'verify', 'Checked 8 claims against the transcript. 6 hold.', 'verified'],
  ['00:15', 'verify', '“All 14 tests pass.” The last test run before it shows 2 failed.', 'contradicted'],
  ['00:16', 'verify', '“Deployed to staging.” No deploy command is recorded.', 'unverified'],
  ['00:22', 'script', 'Wrote 5 narration lines.', ''],
  ['00:27', 'ground', 'Line 1 rests on entry 1, the prompt.', 'verified'],
  ['00:28', 'ground', 'Line 2 rests on entry 204.', 'verified'],
  ['00:29', 'ground', 'Line 3 rests on entry 209 and the diff of send.ts.', 'verified'],
  ['00:30', 'ground', 'Line 4, “The tests now pass reliably.”, has no source. Sent back to script.', 'contradicted'],
  ['00:33', 'script', 'Line 4 rewritten: “The last run shows 14 tests passing.”', ''],
  ['00:34', 'ground', 'Line 4 rests on entry 219.', 'verified'],
  ['00:35', 'ground', 'Checking line 5 against entries 204 and 212', 'live'],
];

const GATE = [
  ['Grounding', 'Every narration line cites a recorded entry.'],
  ['Secrets', 'No key or token appears in a frame or a line.'],
  ['Cost', 'The run stays inside its $0.60 budget.'],
  ['Review', 'A person approves the reel.'],
];

export function runPage() {
  return `<!doctype html>
${COMMENT('run in progress (app)')}
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Run in progress: acme/api — Dailies</title>
${FONTS}
<style>${BASE_CSS}${PILL_CSS}${APP_CSS}
  .state i{animation:pulse 1.6s ease-in-out infinite}
  @keyframes pulse{50%{opacity:.25}}
  @media (prefers-reduced-motion:reduce){.state i,.live i{animation:none}}

  .lead{display:flex;align-items:flex-end;justify-content:space-between;gap:20px 48px;flex-wrap:wrap;padding:6px 0 0}
  .lead h2{display:block;font:300 clamp(24px,2.5vw,34px)/1.15 var(--disp);letter-spacing:-.022em}
  .lead h2 b{font-weight:800}
  .cost{display:flex;align-items:center;gap:16px;margin:0 0 4px}
  .cost dt{font:400 14.5px/1.2 var(--txt);color:var(--glass-400)}
  .cost dd{margin:0;display:flex;align-items:center;gap:14px;font:600 20px/1 var(--txt)}
  .cost dd small{font:400 15px/1 var(--txt);color:var(--glass-200)}
  .cost .meter{height:17px;width:auto}

  .rail{margin:10px calc(50% - 50vw) 0;overflow-x:auto;overflow-y:hidden}
  .stages{display:block;width:100%;min-width:1000px;height:auto}

  .below{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,470px);gap:36px clamp(36px,5vw,76px);align-items:start;margin-top:8px}

  /* live event log */
