6	// budget drawn as perforations: one hole per 5 cents
7	export function meter(spent, budget, o = {}) {
8	  const { n = 12, w = 9, h = 13, gap = 5, label = '' } = o;
9	  const lit = (spent / budget) * n;
10	  let s = '';
11	  for (let i = 0; i < n; i++) {
12	    const x = i * (w + gap), part = Math.max(0, Math.min(1, lit - i));
13	    s += `<rect x="${x}" width="${w}" height="${h}" rx="2.2" fill="#1e2b27"/>`;
14	    if (part > 0) s += `<rect x="${x}" width="${f(w * part)}" height="${h}" rx="${part === 1 ? 2.2 : 1}" fill="#dfe6e3"/>`;
15	  }
16	  return `<svg class="meter" width="${n * (w + gap) - gap}" height="${h}" viewBox="0 0 ${n * (w + gap) - gap} ${h}" role="img" aria-label="${label}">${s}</svg>`;
