import { FONTS, DEFS, BASE_CSS, COMMENT, PERF_H_SM } from './defs.mjs';
import { f, mark } from './lib.mjs';
import { FILM_CSS, PILL_CSS, hunkHTML, loupeSVG, lensToken } from './parts.mjs';
import * as F from './frames.mjs';

// budget drawn as perforations: one hole per 5 cents
export function meter(spent, budget, o = {}) {
  const { n = 12, w = 9, h = 13, gap = 5, label = '' } = o;
  const lit = (spent / budget) * n;
  let s = '';
  for (let i = 0; i < n; i++) {
    const x = i * (w + gap), part = Math.max(0, Math.min(1, lit - i));
    s += `<rect x="${x}" width="${w}" height="${h}" rx="2.2" fill="#1e2b27"/>`;
    if (part > 0) s += `<rect x="${x}" width="${f(w * part)}" height="${h}" rx="${part === 1 ? 2.2 : 1}" fill="#dfe6e3"/>`;
  }
  return `<svg class="meter" width="${n * (w + gap) - gap}" height="${h}" viewBox="0 0 ${n * (w + gap) - gap} ${h}" role="img" aria-label="${label}">${s}</svg>`;
}

export const APP_CSS = `
  body{min-height:100vh;background:radial-gradient(90vw 70vh at 30% 8%,#151d1b 0%,#0d1211 62%) no-repeat,var(--lb-950)}
  .page{width:min(1368px,calc(100vw - 48px));margin:0 auto;padding:20px 0 44px}
  body{overflow-x:clip}
  .top{display:flex;align-items:center;gap:14px 28px;flex-wrap:wrap;padding:8px 0 26px}
  .mark{font:600 19px/1 var(--disp);letter-spacing:-.01em;text-decoration:none}
  .crumb{display:flex;align-items:baseline;gap:8px 16px;flex-wrap:wrap;flex:1 1 auto;min-width:0}
  .crumb h1{margin:0;font:600 19px/1.1 var(--disp);letter-spacing:-.015em}
  .crumb .win{font:400 13px/1.2 var(--mono);color:var(--glass-400)}
  .state{display:inline-flex;align-items:center;gap:9px;font:500 14px/1 var(--txt);color:var(--glass-200);padding:10px 16px;border-radius:999px;border:1px solid rgba(238,243,241,.16)}
  .state i{width:7px;height:7px;border-radius:50%;background:var(--white)}
  h2{margin:0;display:flex;align-items:baseline;gap:12px;font:600 15px/1.2 var(--disp);letter-spacing:-.005em}
  h2 span{font:400 12.5px/1 var(--mono);color:var(--glass-400);letter-spacing:0}
  .vp{display:inline-block;font:800 10.5px/1 var(--disp);letter-spacing:.05em;padding:6.5px 11px 6px;border-radius:999px;white-space:nowrap}
  .vp.solid{background:var(--pencil);color:#0d1211}
  .vp.line{box-shadow:inset 0 0 0 1.5px var(--pencil);color:var(--pencil)}
  .meter{display:block}
  /* the wide pill at the foot: facts on the left, what a person does on the right */
  .bar{display:flex;align-items:center;justify-content:space-between;gap:18px 32px;flex-wrap:wrap;margin-top:36px;padding:10px 10px 10px 38px;border-radius:999px;background:rgba(7,10,9,.62);border:1px solid rgba(238,243,241,.2)}
  .facts{display:flex;align-items:center;gap:14px clamp(24px,3.6vw,56px);flex-wrap:wrap;margin:0}
  .facts div{display:flex;align-items:baseline;gap:10px;min-width:0}
  .facts dt{font:400 14px/1.2 var(--txt);color:var(--glass-400)}
  .facts dd{margin:0;display:flex;align-items:center;gap:12px;font:600 16px/1.2 var(--txt)}
  .facts dd small{font:400 14px/1.2 var(--txt);color:var(--glass-200);white-space:nowrap}
  .facts dd.id{font:400 13.5px/1.2 var(--mono);color:var(--glass-200)}
  .acts{display:flex;gap:8px;flex-wrap:wrap}
  .acts .btn{padding:17px 28px;font-size:17px}
`;

const LINES = [
  { t: '0:04', text: 'The request was a retry with backoff for the webhook sender.', v: 'verified', n: 1,
    ev: `<div class="fr lit"><p class="fr-h"><b>Transcript entry</b><span>session 1 · entry 1 · 23:40</span></p><p class="entry"><span class="dim">prompt</span> Add retry with backoff to the webhook sender, and make sure the tests cover the timeout path.</p></div>` },
  { t: '0:15', text: 'The first test run failed twice.', v: 'verified', n: 1,
    ev: `<div class="fr lit"><p class="fr-h"><b>Transcript entry</b><span>session 3 · entry 204 · 02:09</span></p><p class="entry"><span class="dim">$</span> pnpm test<br>Tests&nbsp; 2 failed | 12 passed</p></div>` },
  { t: '0:27', text: 'The sender now retries 4 times and waits longer after each attempt.', v: 'verified', n: 2, open: true },
  { t: '0:44', text: 'The last run shows 14 tests passing.', v: 'verified', n: 1,
    ev: `<div class="fr lit"><p class="fr-h"><b>Transcript entry</b><span>session 4 · entry 219 · 05:48</span></p><p class="entry"><span class="dim">$</span> pnpm test<br>Tests&nbsp; 14 passed</p></div>` },
  { t: '0:56', text: 'In session 3 the agent reported success before that run existed.', v: 'contradicted', n: 2,
    ev: `<div class="fr lit"><p class="fr-h"><b>Transcript entry</b><span>session 3 · entry 212 · 02:14</span></p><p class="entry"><span class="dim">agent</span> All 14 tests pass.</p></div><div class="fr lit"><p class="fr-h"><b>Transcript entry</b><span>session 3 · entry 204 · 02:09</span></p><p class="entry"><span class="dim">$</span> pnpm test<br>Tests&nbsp; 2 failed | 12 passed</p></div>` },
];

export function reelPage() {
  const poster = F.title({ poster: true, p: 'po' });
  const thumbs = [['Title', F.title()], ['Prompt', F.prompt()], ['Terminal', F.terminal()], ['Diff', F.diff()], ['Stats', F.stats()], ['Flag', F.flag()], ['End', F.end()]];
  const rowLens = lensToken({ line: '+  for (let attempt = 0; attempt < 4; attempt++) {', from: 25, len: 11, size: 13.5, above: "-  if (!res.ok) throw new Error('webhook failed');", below: "+    const res = await fetch(url, { method: 'POST', body,", seed: 4, ringPad: 10, sw: 3, filter: 'pencilSm' });
  const openEv = `<div class="fr lit"><p class="fr-h"><b>Transcript entry</b><span>session 3 · entry 209 · 02:12</span></p><p class="entry">Edit <span class="dim">src/webhooks/</span>send.ts <span class="dim">&nbsp;+18 −4</span></p></div>
          <div class="fr lit"><p class="fr-h"><b>Diff hunk</b><span>src/webhooks/send.ts</span></p>${hunkHTML()}</div>`;

  return `<!doctype html>
${COMMENT('reel page (app)')}
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>acme/api, last night — Dailies</title>
${FONTS}
<style>${BASE_CSS}${PILL_CSS}${FILM_CSS}${APP_CSS}
  .grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,540px);gap:34px 40px;align-items:start}
  .watch{grid-column:1;min-width:0}
  .narr{grid-column:2;grid-row:1 / span 2;min-width:0}
  .flags{grid-column:1;min-width:0}

  .player{position:relative;aspect-ratio:16/9;border-radius:20px;overflow:hidden;background:var(--lb-950);box-shadow:0 0 0 1px rgba(238,243,241,.1),0 40px 90px -30px #000}
  .player>svg{display:block;width:100%;height:100%}
  .playhit{position:absolute;left:11.1%;top:28.2%;width:40.2%;aspect-ratio:1;border-radius:50%;border:0;background:none;cursor:pointer;padding:0}
  .playhit:focus-visible{outline-offset:-6px}

  /* the reel as a strip of its own frames; the ring is where the loupe is */
  .scrub{margin-top:16px}
  .frames{list-style:none;margin:0;padding:17px 6px;display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;background:${PERF_H_SM} 0 3px/14px 12px repeat-x,${PERF_H_SM} 0 calc(100% - 3px)/14px 12px repeat-x,var(--em-950);box-shadow:inset 0 1px rgba(238,243,241,.16),inset 0 -1px rgba(238,243,241,.16)}
  .th{position:relative;aspect-ratio:16/9}
  .th svg{display:block;width:100%;height:100%;border-radius:3px;opacity:.5}
  .th.on svg{opacity:1}
  .th.on::after{content:"";position:absolute;left:50%;top:50%;width:calc(100% - 8px);aspect-ratio:1;transform:translate(-50%,-50%);border-radius:50%;pointer-events:none;
    background:radial-gradient(circle at 30% 22%,rgba(255,255,255,.22),rgba(255,255,255,0) 34%);
    box-shadow:inset 0 0 0 1px rgba(238,243,241,.4),0 0 0 3px #0a0d0c,0 0 0 9px #27312e,0 0 0 10px rgba(238,243,241,.3),0 12px 26px 6px rgba(0,0,0,.6)}
  .ticks{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px;padding:16px 6px 0;font:400 12px/1.2 var(--mono);color:var(--glass-400)}
  .ticks span{display:flex;align-items:center;justify-content:center;gap:5px;min-height:18px;white-space:nowrap}
  .ticks span:first-child{justify-content:flex-start}
  .ticks span:last-child{justify-content:flex-end}
  .ticks b{font-weight:500;color:var(--white)}

  /* narration */
  .rows{list-style:none;margin:14px 0 0;padding:0}
  .row summary{list-style:none;display:grid;grid-template-columns:44px minmax(0,1fr) auto 26px;column-gap:12px;align-items:start;padding:13px 0;cursor:pointer;border-radius:6px}
  .row summary::-webkit-details-marker{display:none}
  .row .t{padding-top:3px;font:400 12.5px/1.3 var(--mono);color:var(--glass-400)}
  .row .x{font:400 16.5px/1.38 var(--txt);color:var(--glass-200);text-wrap:pretty}
  .row .n{padding-top:4px;font:400 11.5px/1.3 var(--mono);color:var(--glass-400);white-space:nowrap}
  .row .mk{margin-top:-2px}
  .row summary:hover .x{color:var(--white)}
  .row[open] summary,.row details[open] summary{position:relative}
  .row.open summary{grid-template-columns:44px minmax(0,1fr) 150px;min-height:100px;padding-bottom:16px}
  .row.open .t{color:var(--white)}
  .row.open .x{font-weight:600;color:var(--white)}
  .row.open .n,.row.open summary>.mk{display:none}
  .row-loupe{position:absolute;right:-22px;top:2px;width:188px;height:188px;z-index:2;pointer-events:none}
  .ev{margin:0 0 14px}
  .narr .film{padding-left:31px;padding-right:31px}
  .narr .fr{padding:14px 15px 16px}
  .narr .hunk{font-size:12px}
  .row.open .ev .fr:first-child{padding-right:132px}

  /* flags */
  .flaglist{list-style:none;margin:6px 0 0;padding:0}
  .flag{display:grid;grid-template-columns:58px minmax(0,1fr) auto;column-gap:14px;align-items:center;padding:18px 0}
  .flag+.flag{border-top:1px solid var(--hair)}
  .flag .said{margin:0;font:600 21px/1.25 var(--txt)}
  .flag .rec{margin:5px 0 0;font:400 15.5px/1.4 var(--txt);color:var(--glass-200)}
  .flag .side{display:grid;justify-items:end;gap:9px}
  .flag .src{font:400 12px/1.2 var(--mono);color:var(--glass-400);white-space:nowrap}
  .flag.minor{grid-template-columns:58px minmax(0,1fr) auto;padding:14px 0}
  .flag.minor .mk{justify-self:center}
  .flag.minor .said{font-size:17px}
  .flag.minor .rec{font-size:14.5px}

  @media (max-width:980px){
    .grid{grid-template-columns:minmax(0,1fr);gap:30px}
    .watch,.narr,.flags{grid-column:1;grid-row:auto}
  }
  @media (max-width:560px){
    .page{padding-top:12px}
    .top{padding-bottom:18px;gap:10px 16px}
    h2{flex-wrap:wrap;gap:4px 12px}
    .state{order:3;padding:8px 13px;font-size:13px}
    .crumb{flex-basis:100%;order:4}
    .player{border-radius:14px}
    .frames{gap:3px;padding:15px 4px}
    .th.on::after{box-shadow:inset 0 0 0 1px rgba(238,243,241,.4),0 0 0 2px #0a0d0c,0 0 0 5px #27312e,0 0 0 6px rgba(238,243,241,.3),0 8px 16px 2px rgba(0,0,0,.6)}
    .ticks{gap:3px;padding:14px 4px 0;font-size:11px}
    .row summary{grid-template-columns:38px minmax(0,1fr) 22px;column-gap:10px}
    .row .n{display:none}
    .row .x{font-size:16px}
    .row.open summary{grid-template-columns:38px minmax(0,1fr) 104px;min-height:112px}
    .row-loupe{width:150px;height:150px;right:-20px;top:6px}
    .row.open .ev .fr:first-child{padding-right:13px;padding-top:42px}
    .narr .film{padding-left:30px;padding-right:30px}
    .narr .fr{padding:13px 12px 15px}
    .narr .hunk{font-size:11.5px}
    .entry{font-size:12.5px}
    .flag{grid-template-columns:44px minmax(0,1fr);row-gap:10px}
    .flag .mk{width:36px;height:36px}
    .flag.minor .mk{width:28px;height:28px}
    .flag.minor{grid-template-columns:44px minmax(0,1fr)}
    .flag .side{grid-column:2;justify-items:start;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
    .flag .said{font-size:19px}
    .bar{border-radius:26px;padding:20px 12px 12px 22px;margin-top:26px}
    .facts{gap:10px 26px}
    .acts{width:100%;margin-left:-10px;width:calc(100% + 10px)}
    .acts .btn{flex:1 1 0;padding:16px 12px;font-size:16px}
  }
</style>
</head>
<body>
${DEFS}
<div class="page">
  <header class="top">
    <a class="mark" href="landing.html">Dailies</a>
    <div class="crumb"><h1>acme/api</h1><span class="win">last night, 23:40 – 06:10</span></div>
    <span class="state"><i></i>Waiting for your review</span>
  </header>

  <main class="grid">
    <section class="watch" aria-label="The reel">
      <div class="player">
        ${F.svgFrame(poster)}
        <button class="playhit" type="button" aria-label="Play the reel, 1 minute 14 seconds"></button>
      </div>
      <div class="scrub">
        <ol class="frames" aria-label="The reel, scene by scene">
          ${thumbs.map(([name, fr], i) => `<li class="th${i === 3 ? ' on' : ''}"${i === 3 ? ' aria-current="true"' : ''}>${F.svgFrame(fr).replace('role="img"', 'role="img" preserveAspectRatio="xMidYMid slice"')}</li>`).join('\n          ')}
        </ol>
        <div class="ticks" aria-hidden="true"><span>0:00</span><span></span><span></span><span><b>cued 0:27</b></span><span></span><span>${mark('contradicted', 16, { sw: 6 })}${mark('unverified', 16, { sw: 6 })}</span><span>1:14</span></div>
      </div>
    </section>

    <section class="narr" aria-label="Narration and its sources">
      <h2>Narration <span>5 lines, each opens to its sources</span></h2>
      <ol class="rows">
        ${LINES.map((l) => `<li class="row${l.open ? ' open' : ''}"><details${l.open ? ' open' : ''}>
          <summary><span class="t">${l.t}</span><span class="x">${l.text}</span><span class="n">${l.n} ${l.n > 1 ? 'sources' : 'source'}</span>${mark(l.v, 26, { seed: 3 + l.t.length + l.n })}${l.open ? loupeSVG({ cls: 'row-loupe', lens: rowLens, s: 0.243, small: true, pad: 6, label: 'Under the loupe: attempt < 4, verified' }) : ''}</summary>
          <div class="ev film">${l.open ? openEv : l.ev}</div>
        </details></li>`).join('\n        ')}
      </ol>
    </section>

    <section class="flags" aria-label="Flags">
      <h2>Flags <span>2 of 8 claims</span></h2>
      <ul class="flaglist">
        <li class="flag">
          ${mark('contradicted', 46, { sw: 5 })}
          <div><p class="said">“All 14 tests pass.”</p><p class="rec">Last test run before this message: 2 failed.</p></div>
          <div class="side"><span class="vp solid">CONTRADICTED</span><span class="src">session 3 · entry 212</span></div>
        </li>
        <li class="flag minor">
          ${mark('unverified', 34, { sw: 5 })}
          <div><p class="said">“Deployed to staging.”</p><p class="rec">No deploy command is recorded.</p></div>
          <div class="side"><span class="vp line">UNVERIFIED</span><span class="src">session 4 · entry 226</span></div>
        </li>
      </ul>
    </section>
  </main>

  <footer class="bar">
    <dl class="facts">
      <div><dt>Duration</dt><dd>1:14</dd></div>
      <div><dt>Cost</dt><dd>$0.31 <small>of $0.60</small>${meter(0.31, 0.6, { label: '31 cents spent of a 60 cent budget' })}</dd></div>
      <div><dt>Trace</dt><dd class="id">trc_8c41f2e0b7a9</dd></div>
    </dl>
    <div class="acts"><button class="btn" type="button">Request changes</button><button class="btn go" type="button">Approve</button></div>
  </footer>
</div>
</body>
</html>
`;
}

