84	function stepSVG(n, inner, label, extra = '') {
85	  let perfs = '';
86	  for (let i = 0; i < 8; i++) { const x = f(i * 80 + 23.25); perfs += `<rect x="${x}" y="33.5" width="33.5" height="47" rx="6.4"/><rect x="${x}" y="509.3" width="33.5" height="47" rx="6.4"/>`; }
87	  return `<svg viewBox="0 0 640 590" role="img" aria-label="${label}"><rect y="-1" width="640" height="592" fill="#070a09"/><g fill="#1c2724">${perfs}</g><path d="M0,0H640M0,590H640" stroke="#eef3f1" stroke-opacity=".16" stroke-width="2"/><rect x="16.7" y="92.5" width="606.5" height="404" rx="6.7" fill="#131c19"/>${inner}${tx('mono', 60, 580, 19, n, { op: 0.62 })}${extra}</svg>`;
88	}
89	function steps() {
90	  const s1 = stepSVG('1', `<rect x="58" y="246" width="524" height="96" rx="48" fill="#070a09" fill-opacity=".72" stroke="#eef3f1" stroke-opacity=".28" stroke-width="2"/>${tx('code', 96, 303, 25, 'github.com/acme/api', { op: 0.92 })}<rect x="398" y="258" width="172" height="72" rx="36" fill="#ffd60a"/>${tx('txt', 484, 303, 25, 'Paste', { w: 600, anchor: 'middle', fill: '#0d1211' })}`, 'Frame 1: a repository address pasted into a field.', tx('mono', 80, 26, 13, 'DAILIES SAFETY FILM', { op: 0.26, ls: 3 }));
91	  const lens = `<circle r="1200" fill="#2a3f38"/><g transform="rotate(-2)">${tx('mono', 0, -104, 20, 'agent, 02:14', { anchor: 'middle', op: 0.62 })}${pencil(crossD(0, 4, 420, 190, { seed: 3 }), { sw: 12, filter: 'pencil' })}<text class="disp" text-anchor="middle" font-size="50" font-weight="600" fill="#eef3f1" letter-spacing="-1.5" stroke="#2a3f38" stroke-width="8" stroke-linejoin="round" paint-order="stroke"><tspan x="0" y="-12">“All 14</tspan><tspan x="0" y="52">tests pass.”</tspan></text></g>`;
92	  const s2 = stepSVG('2', '', 'Frame 2, under the loupe: the agent said All 14 tests pass, crossed out in pencil.', loupe({ x: 320, y: 295, s: 0.92, lens }));
93	  const s3 = stepSVG('3', `<circle cx="150" cy="294" r="60" fill="none" stroke="#eef3f1" stroke-opacity=".75" stroke-width="3"/><path d="M136,268 L180,294 L136,320Z" fill="#eef3f1" stroke="#eef3f1" stroke-width="7" stroke-linejoin="round"/><rect x="262" y="216" width="304" height="70" rx="35" fill="#ffd60a"/>${tx('txt', 414, 260, 25, 'Approve', { w: 600, anchor: 'middle', fill: '#0d1211' })}<rect x="262" y="302" width="304" height="70" rx="35" fill="none" stroke="#eef3f1" stroke-opacity=".42" stroke-width="2"/>${tx('txt', 414, 346, 25, 'Request changes', { w: 600, anchor: 'middle' })}`, 'Frame 3: a play button, Approve and Request changes.');
94	  return [s1, s2, s3];
