98	function chip(kind) {
99	  let perfs = '';
100	  for (let i = 0; i < 8; i++) { const x = f(i * 40 + 11.6); perfs += `<rect x="${x}" y="16.7" width="16.7" height="23.5" rx="3.2"/><rect x="${x}" y="254.7" width="16.7" height="23.5" rx="3.2"/>`; }
101	  const q = (a, b, y = 136, size = 31) => `<text class="disp" text-anchor="middle" font-size="${size}" font-weight="600" fill="#eef3f1" letter-spacing="-.8" stroke="#263a33" stroke-width="6" stroke-linejoin="round" paint-order="stroke"><tspan x="160" y="${y}">${a}</tspan>${b ? `<tspan x="160" y="${y + 40}">${b}</tspan>` : ''}</text>`;
102	  let inner = '';
103	  if (kind === 'verified') inner = tx('disp', 160, 160, 35, '14 passed', { w: 800, anchor: 'middle', ls: -1 }) + pencil(ringD(160, 148, 139, 52, { seed: 3, start: Math.PI * 0.88 }), { sw: 6.5, filter: 'pencil' });
104	  if (kind === 'contradicted') inner = pencil(crossD(160, 148, 252, 150, { seed: 6 }), { sw: 8, filter: 'pencil' }) + q('“All 14', 'tests pass.”');
105	  if (kind === 'stale') inner = tx('disp', 160, 146, 35, '14 passed', { w: 800, anchor: 'middle', ls: -1, op: 0.82 }) + pencil(ringD(160, 134, 139, 50, { seed: 8, turns: 1, drift: 0 }), { sw: 6.5, filter: 'pencil', dash: '22 15' }) + tx('code', 160, 222, 15, 'then send.ts was edited', { anchor: 'middle', op: 0.66 });
106	  if (kind === 'unverified') inner = `<text class="disp" font-size="27" font-weight="600" fill="#eef3f1" letter-spacing="-.8"><tspan x="32" y="106">“Deployed</tspan><tspan x="32" y="141">to staging.”</tspan></text>` + pencil(qD(246, 192, 92), { sw: 8, filter: 'pencil' });
107	  return `<svg viewBox="0 0 320 295" aria-hidden="true"><rect width="320" height="295" fill="#070a09"/><g fill="#1c2724">${perfs}</g><rect x="8.4" y="46.2" width="303.2" height="202" rx="4" fill="url(#pic)"/>${inner}</svg>`;
108	}
