416	    lens.setAttribute('transform','translate('+(-16*t).toFixed(1)+' '+(-132*t).toFixed(1)+')');
417	    skirt.setAttribute('transform','translate('+(7*t).toFixed(1)+' '+(44*t).toFixed(1)+')');
418	    spec.setAttribute('transform','rotate('+(-16*t).toFixed(1)+')');
419	  }
