    <ol class="chapters" aria-label="The four parts of the sample reel">
      <li class="on" style="--s:12"><span class="t">0:00</span><span class="n">The problem</span></li>
      <li style="--s:15"><span class="t">0:12</span><span class="n">Key decisions</span></li>
      <li style="--s:17"><span class="t">0:27</span><span class="n">Implementation</span></li>
      <li style="--s:30"><span class="t">0:44</span><span class="n">Recorded validation</span></li>
    </ol>
  </div>
</section>

<section class="sec night">
  <div class="wrap">
    <h2>How it reads the night</h2>
  </div>
  <ol class="steps">
    <li class="step">
      <figure>${s1}</figure>
      <div class="cap"><h3>Paste a repo</h3><p>Dailies reads last night's Entire checkpoints: every prompt, command, edit and message.</p></div>
