          </div>
          <div class="fr lit">
            <p class="fr-h"><b>Diff hunk</b><span>src/webhooks/send.ts</span></p>
            ${hunkHTML()}
          </div>
        </div>
      </div>
    </div>
  </div>
</section>

<section class="sec verdicts">
  <div class="wrap">
    <h2>Four verdicts</h2>
    <p class="lede">Every claim an agent made leaves the night with one of four pencil marks.</p>
    <ul class="vgrid">
      <li>${chip('verified')}<h3>Verified</h3><p>The record shows it.</p></li>
      <li>${chip('contradicted')}<h3>Contradicted</h3><p>The record shows otherwise.</p></li>
      <li>${chip('stale')}<h3>Stale</h3><p>The code was edited after the last passing run.</p></li>
      <li>${chip('unverified')}<h3>Unverified</h3><p>Nothing in the record either way.</p></li>
    </ul>
  </div>
</section>

<section class="sec cli">
  <div class="wrap cli-grid">
    <div>
      <h2>Runs where your agents run</h2>
      <p class="lede">Dailies is a plugin for the Entire CLI.</p>
    </div>
    <div class="cmd"><span class="ps" aria-hidden="true">$</span><code>entire dailies run .</code><button class="btn" type="button">Copy</button></div>
