</section>
</main>

<footer>
  <div class="wrap foot">
    <a class="mark" href="#hero">Dailies</a>
    <p>Verification rests on what the session recorded.</p>
    <a class="gh" href="https://github.com/">GitHub</a>
  </div>
</footer>

