(function(){
  // signature interaction: scrolling slides the film under the glass. The magnified frame travels one way,
  // the refraction in the clear skirt the other, and the highlight turns.
  var lens=document.getElementById('lensShift'), skirt=document.getElementById('skirtShift'), spec=document.getElementById('glassSpec');
  var still=window.matchMedia('(prefers-reduced-motion: reduce)').matches, tick=false;
  function shift(){
    tick=false;
    var t=Math.min(window.scrollY/window.innerHeight,1.15);
    lens.setAttribute('transform','translate('+(-16*t).toFixed(1)+' '+(-132*t).toFixed(1)+')');
    skirt.setAttribute('transform','translate('+(7*t).toFixed(1)+' '+(44*t).toFixed(1)+')');
    spec.setAttribute('transform','rotate('+(-16*t).toFixed(1)+')');
  }
  if(!still){
    window.addEventListener('scroll',function(){if(!tick){tick=true;requestAnimationFrame(shift)}},{passive:true});
    shift();
  }
  var copy=document.querySelector('.cmd .btn');
  if(copy) copy.addEventListener('click',function(){
    if(navigator.clipboard) navigator.clipboard.writeText('entire dailies run .');
    copy.textContent='Copied'; setTimeout(function(){copy.textContent='Copy'},1600);
  });
})();
</script>
</body>
</html>
